import { content as D } from './data/activities.js';
const $=sel=>document.querySelector(sel),root=$('#app'),toast=$('#toast'),KEY='harbourline-facilitation-v8';
const fresh=()=>({screen:'home',step:0,tab:'',index:0,selected:{},checked:{},flipped:{},swot:{},swotSelected:null,swotReveal:false,concerns:[],concernsReveal:false,issueReveal:false,alternativesReveal:false,recommendationReveal:false,votes:[0,0,0],studentAlternative:null,issueStatement:'',map:{},mapSelected:null,mapReveal:false,vrioIndex:0,vrioTest:0,vrioReveal:false,chainAnswer:null,chainReveal:false,facilitator:false,projector:false,teams:[{name:'A',score:0},{name:'B',score:0},{name:'C',score:0}],teamMode:true,teamCount:3,currentTeam:0,attempted:[],resolved:{},studentResources:[],studentConcerns:[],sortIndex:0,sortPlaced:{},sortSelected:null,sortReveal:false,resourceSelected:null,scoreTile:null,resourcePlaced:{},resourceReveal:false,pestelSummary:false,swotIndex:0,swotExtras:{S:[],W:[],O:[],T:[]},swotOrder:[],swotFeedback:{},swotWrongAttempts:{},swotExtraAwards:{},summaryView:null,summaryHistory:{},concernRank:[],forceRatings:{},skippedEvidence:{},vrioJudgments:{},collection:{},roundFeedback:{},roundResults:{},roundAttempts:{},studentAnswers:{},tileOrder:{},studentIndex:0,timer:{seconds:300,left:300,running:false,open:false,endAt:null}});
let s=fresh();try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old){s={...s,...old,facilitator:false,timer:{...s.timer,...old.timer,running:false,open:false,endAt:null}}}}catch{}
const H=x=>String(x??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const btn=(label,act,cls='secondary',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${label}</button>`;
const soundWrong=()=>{try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=new AC();const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(290,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(180,ctx.currentTime+.19);g.gain.setValueAtTime(.07,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.21);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.22);o.onended=()=>ctx.close()}catch{}};
const tag=x=>`<span class="tag">${H(x)}</span>`, ref=x=>`<small class="ref">Source: ${H(x)} · Harbourline Creative fictional case / BADM 470 course materials</small>`;
const result=(name,desc,source)=>`<div class="result"><strong>✦ ${H(name)}</strong><p>${H(desc)}</p>${source?ref(source):''}</div>`;
const tabs=(arr,cur)=>`<div class="tabs">${arr.map(([id,n])=>btn(H(n),'tab',cur===id?'active':'secondary',`data-value="${id}"`)).join('')}</div>`;
function choose(items,selected,act='pick'){return `<div class="choices">${items.map((x,i)=>`<button class="choice ${i===selected?'selected':''}" data-act="${act}" data-value="${i}"><b>${'ABCD'[i]||'•'}</b><span>${H(x)}</span></button>`).join('')}</div>`}
function checkButtons(allowed=true,label='Check answer'){return `<div class="buttons">${btn(label,'check','primary',allowed?'':'disabled')}${btn('Reveal / facilitator','reveal','outline')}${btn('Reset round','reset','secondary')}</div>`}
const panel=content=>`<section class="panel">${content}</section>`;
const header=(heading,intro)=>`<div class="heading"><h1>${H(heading)}</h1><p>${H(intro)}</p></div>`;
const qkey=()=>`${s.step}:${s.tab}:${s.index}`;

const COLLECTION_KEYS=['pestel','forces','cards','vrio'];
const bankOf=t=>{
 const samples=t==='pestel'?D.pestel.slice(0,5).map(q=>({...q,text:q.statement})):t==='forces'?D.forces.map(q=>({...q,text:q.statement})):t==='cards'?D.resources.map(q=>({...q,text:q.front})):D.vrio.map(q=>({...q,text:q.title}));
 const own=(s.studentAnswers[t]||[]).filter(q=>q.text).map(q=>({...q,id:'own-'+t+'-'+q.group,student:true,source:'Class submission',explanation:'Group suggestion. Classification reflects class interpretation, not a marked answer.'}));
 const all=[...samples,...own];const order=s.tileOrder[t];return order?.length===all.length?order.map(i=>all[i]):all;
};
const roundId=()=>s.step===0?'quiz:'+s.index:s.step===1?`${s.tab||'pestel'}:${s.index}`:s.step===2?(s.tab==='vrio'?`vrio:${s.vrioIndex}:${s.vrioTest}`:`cards:${s.index}`):`stage:${s.step}:${s.scoreTile||s.index}`;
const feedback=()=>s.roundFeedback[roundId()]||null;
function grade(correct,expected,explanation,source,submitted,student=false){
 const id=roundId();if(s.roundResults[id])return;
 const tried=s.roundAttempts[id]||[];if(tried.includes(s.currentTeam))return message('That group already tried this tile.');
 const group=s.currentTeam;
 if(correct){s.teams[group].score+=1;s.roundResults[id]=true;s.checked[id]=true;s.roundFeedback[id]={good:true,group,submitted,expected,explanation,source,student};s.roundAttempts[id]=[];message('+1 point for Group '+s.teams[group].name)}
 else {soundWrong();s.roundFeedback[id]={good:false,group,submitted,expected:null,explanation:'Incorrect — chance passes to the next group.',source:null};tried.push(group);s.roundAttempts[id]=tried;if(tried.length>=3){s.roundFeedback[id].allTried=true;message('All three groups tried; reveal the answer or skip.')}else{let n=(group+1)%3;while(tried.includes(n))n=(n+1)%3;s.currentTeam=n;message('Incorrect — Group '+s.teams[n].name+' gets the next chance.')}}
}
const statusCard=(body)=>{let f=feedback();return `<div class="hero-card ${f?(f.good?'answered-good':'answered-bad'):''}">${H(body)}</div>${f?`<div class="answer-status ${f.good?'answered-good':'answered-bad'}"><b>${f.good?(f.student?'Class classification recorded — no extra point':f.unscored?'Suggested answer revealed — no point awarded':'✓ Correct! +1 point for Group '+H(s.teams[f.group].name)):'✕ Incorrect — '+(f.allTried?'all groups have tried':'now Group '+H(s.teams[s.currentTeam].name)+'’s turn')}</b>${f.good?`<p><b>Suggested answer:</b> ${H(f.expected||'Student contribution accepted for participation')}</p><p>${H(f.explanation||'')}</p>${f.source?ref(f.source):''}`:f.allTried?`<p>Use “Reveal answer” or move to the next tile.</p>`:''}</div>`:''}`};
function neutralChoice(category){const id=roundId();if(s.roundResults[id])return;const q=(s.step===1?bankOf(s.tab||'pestel')[s.index]:s.tab==='vrio'?bankOf('vrio')[s.vrioIndex]:bankOf('cards')[s.index]);s.roundResults[id]=true;s.roundFeedback[id]={good:true,unscored:true,student:true,group:s.currentTeam,expected:category,submitted:category,explanation:'Class-selected interpretation; no correctness judgment or additional point.',source:null};if(s.step===1&&s.tab==='pestel')s.checked['category:'+q.id]=category;}
function clearChoice(){const id=roundId(),f=s.roundFeedback[id];if(f){if(f.good&&!f.unscored&&s.roundResults[id])s.teams[f.group].score=Math.max(0,s.teams[f.group].score-1);s.currentTeam=f.group;delete s.roundResults[id];delete s.checked[id];delete s.roundFeedback[id];delete s.roundAttempts[id];}if(s.step===1&&(s.tab||'pestel')==='pestel'){const q=bankOf('pestel')[s.index];if(q)delete s.checked['category:'+q.id];}delete s.selected[qkey()];delete s.forceRatings[id];message('Choice cleared; any point awarded for this tile was reversed.');}
function collect(t){const saved=s.studentAnswers[t]||[],skipped=s.skippedEvidence||{};const head={pestel:'PESTEL',forces:'Five Forces',cards:'Resources & Capabilities',vrio:'VRIO'}[t];const count=saved.filter(q=>q.text).length;return header(head+' — Collect Student Ideas','Give students time to find their own evidence. A group may select “No evidence found” instead of contributing a tile.')+panel(`<div class="between">${tag('STUDENTS ANSWER FIRST')}${tag('3 GROUPS · OPTIONAL CONTRIBUTIONS')}</div><h2>What evidence or example did your group identify?</h2><p>Each submitted case example earns its group 1 point and becomes a discussion tile. The prepared bank adds 5 more tiles. Groups without evidence add no tile.</p><div class="collect-grid">${['A','B','C'].map((g,i)=>`<div class="collection-field"><strong>GROUP ${g}</strong><textarea id="collect-${g}" rows="3" spellcheck="true" placeholder="Group ${g} — case example" ${skipped[t]?.[g]?'disabled':''}>${H(saved.find(q=>q.group===g)?.text||'')}</textarea><label class="no-evidence"><input type="checkbox" data-skip="${g}" data-topic="${t}" ${skipped[t]?.[g]?'checked':''}> No evidence found</label></div>`).join('')}</div><p class="small">Spelling suggestions are provided by the browser. Do not invent evidence to fill a group’s box. Student-generated tiles are classified without right/wrong grading.</p><div class="buttons">${btn('Save ideas & start activity →','save-collection','primary',`data-value="${t}"`)}</div>`) }
const isCollection=t=>!s.collection[t];
function tileNav(){s.index++;s.currentTeam=(s.currentTeam+1)%3; if(s.step===1){const t=s.tab||'pestel';if(s.index>=bankOf(t).length){if(t==='pestel')s.pestelSummary=true;else openSummary('forces')}}else if(s.step===2&&s.tab==='cards'){if(s.index>=bankOf('cards').length){s.tab='vrio';s.index=0; s.vrioIndex=0; s.vrioTest=0}}else if(s.step===0){if(s.index>=D.quiz.length)nav(1)}render()}

const forceColors={Low:'low',Moderate:'moderate',High:'high'};
function summaryRows(items,empty='No entries recorded yet.'){return items.length?items.map((v,i)=>`<div class="summary-entry"><span class="summary-num">${i+1}</span><span>${H(v)}</span></div>`).join(''):`<p class="summary-empty">${H(empty)}</p>`}
const summaryNames={quiz:'Case intelligence',pestel:'PESTEL — external factors',forces:'Porter’s Five Forces',cards:'Resources & capabilities',vrio:'VRIO judgments',swot:'SWOT synthesis',concerns:'Priority strategic concerns',issue:'Strategic issue',alternatives:'Strategic alternatives',recommendation:'Class recommendation',congruence:'Line of sight',debrief:'Final class takeaways'};
function summaryScreen(topic){
 const now=topic||'quiz',heading=summaryNames[now]||'Class analysis';let body='',caption='This record reflects the responses collected during your class, not an independently verified assessment.';
 if(now==='quiz'){const results=D.quiz.map((q,i)=>({q,i,f:s.roundFeedback['quiz:'+i]}));body=`<div class="summary-grid two">${results.map(({q,i,f})=>`<article class="summary-card"><small>QUESTION ${i+1}</small><h3>${H(q.question)}</h3><p>${f?.good?H(f.expected||q.options[q.answer]):'Not answered / no correct group response recorded'}</p></article>`).join('')}</div>`;caption='Use case evidence rather than quiz points alone to interpret performance. Financial statements are not provided.';}
 if(now==='pestel'){const bank=bankOf('pestel');body=`<div class="summary-grid three">${pestelOptions.map(cat=>`<article class="summary-card"><h3>${H(cat)}</h3>${summaryRows(bank.filter(q=>s.checked['category:'+q.id]===cat).map(q=>q.text),'No class evidence assigned')}</article>`).join('')}</div>`;caption='Chapter 4: external observation → effect on demand/cost/risk → opportunity or threat. Empty categories may reflect insufficient case evidence.';}
 if(now==='forces'){
  const bank=bankOf('forces'); const forceRows=forceOptions.map(name=>{const rated=bank.flatMap((q,i)=>{const f=s.roundFeedback['forces:'+i],rating=s.forceRatings['forces:'+i];return (f?.good&&f.expected===name&&rating)?[{text:q.text,rating}]:[]});let high=rated.filter(z=>z.rating==='High').length,mid=rated.filter(z=>z.rating==='Moderate').length,low=rated.filter(z=>z.rating==='Low').length;const label=!rated.length?'Not rated':high>mid&&high>=low?'High':low>mid&&low>high?'Low':mid>0?'Moderate':high?'High':'Low';return {name,rated,label}});
  body=`<div class="summary-forces">${forceRows.map(({name,rated,label})=>`<article class="force-summary ${forceColors[label]||'unknown'}"><div class="force-head"><h3>${H(name)}</h3><strong>${H(label.toUpperCase())}</strong></div><div class="force-meter"><i style="width:${label==='High'?100:label==='Moderate'?58:label==='Low'?24:0}%"></i></div>${rated.map(r=>`<div class="force-example"><small>${H(r.rating)} pressure</small><p>${H(r.text)}</p></div>`).join('')||'<p>Not rated by the class.</p>'}</article>`).join('')}</div><div class="summary-insight"><b>Reading the Five Forces</b><p>More <strong>high-pressure</strong> forces generally mean a tougher competitive environment and greater pressure on industry profitability. More <strong>low-pressure</strong> forces tend to be favourable. Ratings are the class’s judgments, not measured facts. A force can be rated differently for different examples; the heading uses the most common recorded rating.</p></div>`;
  caption='High pressure = less attractive competitive conditions; low pressure = more attractive conditions, all else equal. These scores do not calculate Harbourline’s actual profitability.';
 }
 if(now==='cards'){const bank=bankOf('cards'),groups=['Resource','Capability'];body=`<div class="summary-grid two">${groups.map(group=>`<article class="summary-card"><h3>${H(group)}s</h3>${summaryRows(bank.filter((q,i)=>s.roundFeedback['cards:'+i]?.good&&s.roundFeedback['cards:'+i]?.expected===group).map(q=>q.text),'No recorded items')}</article>`).join('')}</div>`;caption='Resources are assets the firm possesses or accesses; capabilities are coordinated activities the firm can perform reliably.';}
 if(now==='vrio'){const bank=bankOf('vrio'),questions=['V · Valuable','R · Rare','I · Costly to imitate','O · Organized'];body=`<div class="summary-grid two">${bank.map((q,i)=>`<article class="summary-card"><h3>${H(q.text)}</h3><div class="vrio-recap">${questions.map((label,j)=>`<div><small>${label}</small><strong>${H(s.vrioJudgments['vrio:'+i+':'+j]||((j>0&&questions.slice(0,j).some((_,k)=>s.vrioJudgments['vrio:'+i+':'+k]==='No'))?'Stopped':'Not selected'))}</strong></div>`).join('')}</div></article>`).join('')}</div>`;caption='Chapter 5: Yes / No / Partly are class judgments. Rarity and imitation may require external comparison not supplied in the case.';}
 if(now==='swot'){const bank=swotBank(),cats=[['S','Strengths'],['W','Weaknesses'],['O','Opportunities'],['T','Threats']];body=`<div class="summary-grid two">${cats.map(([id,name])=>`<article class="summary-card swot-${id}"><h3>${name}</h3>${summaryRows([...bank.filter(q=>s.swot[q.id]===id).map(q=>q.text),...(s.swotExtras[id]||[])],'No class findings added')}</article>`).join('')}</div>`;caption='Chapter 6: strengths and weaknesses are internal; opportunities and threats are external. Classifications are evidence-based discussion judgments.';}
 if(now==='concerns'){const ranked=s.concernRank||[],all=ranked.map(i=>s.studentConcerns[i]?.text).filter(Boolean);body=`<div class="summary-priorities">${summaryRows(all,'No strategic concerns ranked')}</div>`;caption='The ranking indicates class priorities, not an objective score. Use these concerns to formulate the central strategic issue.';}
 if(now==='issue'){body=`<div class="summary-insight"><h3>Class-defined strategic issue</h3><p>${H(s.issueStatement||'No class issue recorded yet.')}</p></div><div class="summary-insight"><small>Facilitators’ example (not the only defensible answer)</small><p>How can Harbourline show clients the value of its marketing expertise and choose a sustainable service model as AI makes routine content easier to replace, given its limited and uneven capabilities?</p></div>`;caption='A strategic issue expresses the central challenge; it should not pre-select a particular solution.';}
 if(now==='alternatives'){body=`<div class="summary-grid three">${allAlternatives().map(x=>`<article class="summary-card"><small>ALTERNATIVE ${H(x.id)}</small><h3>${H(x.title)}</h3><p>${H(x.description)}</p><small>Potential benefit</small><p>${H(x.benefit)}</p><small>Risk</small><p>${H(x.risk)}</p></article>`).join('')}</div>`;caption='These are three defensible approaches, not strategies already adopted by Harbourline.';}
 if(now==='recommendation'){const total=s.votes.reduce((a,b)=>a+b,0);body=`<div class="summary-grid three">${allAlternatives().map((q,i)=>`<article class="summary-card"><h3>${H(q.title)}</h3><div class="summary-vote">${s.votes[i]}</div><p>${total?Math.round(s.votes[i]/total*100):0}% of recorded class votes</p></article>`).join('')}</div>`;caption='Voting reflects class preference; a defensible recommendation still requires a fit, feasibility, risk and assumption check.';}
 if(now==='congruence'||now==='debrief'){const steps=['Evidence','Diagnosis','Strategic issue','Alternatives','Recommendation','Implementation'];body=`<div class="summary-logic">${steps.map((x,i)=>`<div><span>${i+1}</span><strong>${x}</strong></div>`).join('')}</div><div class="summary-insight"><b>Lesson</b><p>Evidence must connect to the issue, the choice must address the issue, and the implementation plan must test the assumptions. Five paid trials do not prove future annual renewals.</p></div>`;}
 let nextLabel={quiz:'Continue to PESTEL',pestel:'Continue to Five Forces',forces:'Continue to Internal Analysis',cards:'Continue to VRIO',vrio:'Continue to SWOT',swot:'Continue to Strategic Concerns',concerns:'Continue to Strategic Issue',issue:'Continue to Alternatives',alternatives:'Continue to Recommendation',recommendation:'Continue to Line of Sight',congruence:'Continue to Closing'}[now]||'Return to class';
 return `<div class="photo-summary">${header(heading+' — Class Summary','PHOTO MOMENT · Invite students to photograph this screen for their strategic-alternatives discussion.')}${panel(`<div class="summary-top"><span>HARBOURLINE CREATIVE · BADM 470</span><strong>CLASS FINDINGS</strong></div>${body}<p class="summary-note">${H(caption)}</p>`)}<div class="summary-actions">${btn('⛶ Fullscreen for photo','fullscreen','outline')}${btn('Back to activity','summary-back','outline')}${btn(nextLabel+' →','summary-next','primary')}</div></div>`;
}
function openSummary(id){s.summaryView=id;s.summaryHistory[id]=true;render();scrollTo(0,0)}
function summaryNext(){const id=s.summaryView;s.summaryView=null;if(id==='quiz')return nav(1);if(id==='pestel'){s.tab='forces';s.index=0;s.pestelSummary=false;render();return;}if(id==='forces')return nav(2);if(id==='cards'){s.tab='vrio';s.vrioIndex=0;s.vrioTest=0;s.index=0;render();return;}if(id==='vrio')return nav(3);if(id==='swot')return nav(4);if(id==='concerns')return nav(5);if(id==='issue')return nav(6);if(id==='alternatives')return nav(7);if(id==='recommendation')return nav(8);if(id==='congruence')return nav(9);render();}
function swotBank(){const bank=D.swot.filter(q=>['S','W','O','T'].includes(q.answer));if(!s.swotOrder.length||s.swotOrder.length!==bank.length){const order=bank.map((_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}s.swotOrder=order}return s.swotOrder.map(i=>bank[i])}
function quiz(){const q=D.quiz[s.index],f=feedback(),id=roundId();const options=q.options.map((text,i)=>`<button class="choice ${f&&f.submitted===i?(f.good?'answered-good':'answered-bad'):''} ${f?.good&&q.answer===i?'answered-good':''}" data-act="quiz-answer" data-value="${i}" ${s.roundResults[id]?'disabled':''}><b>${'ABCD'[i]}</b><span>${H(text)}</span></button>`).join('');return header('Opening: Case Intelligence','15 questions · Every correct answer earns 1 point. A wrong answer passes to the next group.')+panel(`<div class="between">${tag('QUESTION '+(s.index+1)+' / '+D.quiz.length)}${tag(q.source)}</div><h2>${H(q.question)}</h2><div class="choices">${options}</div>${f?`<div class="answer-status ${f.good?'answered-good':'answered-bad'}"><b>${f.good?(f.student?'Class classification recorded — no extra point':f.unscored?'Suggested answer revealed — no point awarded':'✓ Correct! +1 for Group '+s.teams[f.group].name):'✕ Incorrect — '+(f.allTried?'all groups attempted':'Group '+s.teams[s.currentTeam].name+' tries next')}</b>${f.good?`<p><b>Suggested answer: ${'ABCD'[q.answer]}.</b> ${H(q.options[q.answer])}</p><p>${H(q.explanation)}</p>`:''}</div>`:''}<div class="buttons">${btn('Clear choice','clear-choice','outline')}${btn('Reveal suggested answer','show-quiz','outline')}${btn(s.index===D.quiz.length-1?'Go to External Analysis →':'Next question →','next-tile','primary',s.roundResults[id]||f?.allTried?'':'disabled')}</div>`)}
const pestelOptions=['Political','Economic','Sociocultural','Technological','Environmental','Legal','Not evidenced'];
const forceOptions=['Buyer power','Supplier power','Threat of substitutes','Threat of new entrants','Competitive rivalry'];
const levelOptions=['High','Moderate','Low','Significant','High for routine production','Insufficient evidence'];
function chips(options,value,action){return `<div class="chips">${options.map(x=>btn(H(x),action,value===x?'active':'secondary',`data-value="${H(x)}"`)).join('')}</div>`}
function external(){const t=s.tab||'pestel';if(isCollection(t))return collect(t);const bank=bankOf(t),q=bank[s.index],f=feedback(),id=roundId();let html=header('External Analysis',`Chapter 4 · ${t==='pestel'?'PESTEL':"Porter's Five Forces"} · 5 prepared cards + ${bank.filter(q=>q.student).length} class contributions`)+tabs([['pestel','PESTEL'],['forces','Five Forces']],t);if(t==='pestel'&&s.pestelSummary){return summaryScreen('pestel')}
 const selection=s.selected[qkey()]?.force||null;let rating=s.forceRatings[id]||'Moderate';html+=panel(`<div class="between">${tag('TILE '+(s.index+1)+' / '+bank.length)}${tag(q.student?'CLASS SUBMISSION — '+q.group:'PREPARED CASE EVIDENCE')}</div>${statusCard(q.text)}${t==='pestel'?`<p>Choose the most appropriate category. For a class contribution, there is no pre-assigned correct answer.</p><div class="pestel-tiles">${pestelOptions.map(cat=>btn(H(cat),'pestel-answer',f?.submitted===cat?(f.student?'active':f.good?'answered-good':'answered-bad'):'secondary',`data-value="${H(cat)}" ${s.roundResults[id]?'disabled':''}`)).join('')}</div>`:`<p>Which competitive force is illustrated?</p><div class="force-bank">${forceOptions.map(cat=>btn(H(cat),'force-answer',f?.submitted===cat?(f.student?'active':f.good?'answered-good':'answered-bad'):'secondary',`data-value="${H(cat)}" ${s.roundResults[id]?'disabled':''}`)).join('')}</div>${f?.good?`<div class="rating-modal"><h3>How strong is this force?</h3><p>Choose a classroom judgment. This is not graded and earns no points.</p><div class="rating-scale"><span>Low</span><span>Moderate</span><span>High</span></div><input type="range" class="pressure-meter" id="pressure-meter" min="0" max="2" step="1" value="${['Low','Moderate','High'].indexOf(rating)}" aria-label="Competitive force pressure"><strong id="pressure-value">${H(rating)}</strong>${btn('Confirm pressure & continue →','force-finish','primary')}</div>`:''}`}
 <div class="buttons">${btn('Clear choice','clear-choice','outline','')}${btn(q.student?'Keep class interpretation':'Reveal suggested answer','reveal-tile','outline')}${t==='pestel'?btn(s.index===bank.length-1?'PESTEL summary →':'Next tile →','next-tile','primary',s.roundResults[id]||f?.allTried?'':'disabled'):f?.good?'':btn('Next tile →','next-tile','secondary',f?.allTried?'':'disabled')}</div>`);return html}
function internal(){const t=s.tab||'cards';if(isCollection(t))return collect(t);const bank=bankOf(t);let html=header('Internal Analysis',`Chapter 5 · ${t==='cards'?'Resources and capabilities':'VRIO sequential judgment'} · ${t==='cards'?D.resources.length:D.vrio.length} prepared + ${bank.filter(q=>q.student).length} student tiles`)+tabs([['cards','Resources & capabilities'],['vrio','VRIO']],t);if(t==='cards'){const q=bank[s.index],f=feedback(),id=roundId();return html+panel(`<div class="between">${tag('TILE '+(s.index+1)+' / '+bank.length)}${tag(q.student?'CLASS SUBMISSION — '+q.group:'PREPARED CASE EVIDENCE')}</div>${statusCard(q.text)}<p>Is this a Resource (what the agency has) or Capability (what it does)?</p><div class="choices">${['Resource','Capability'].map(x=>btn(H(x),'rc-answer',f?.submitted===x?(f.student?'active':f.good?'answered-good':'answered-bad'):'secondary',`data-value="${x}" ${s.roundResults[id]?'disabled':''}`)).join('')}</div><div class="buttons">${btn('Clear choice','clear-choice','outline','')}${btn('Reveal suggested answer','reveal-tile','outline')}${btn(s.index===bank.length-1?'Continue to VRIO →':'Next tile →','next-tile','primary',s.roundResults[id]||f?.allTried?'':'disabled')}</div>`)}
 const q=bank[s.vrioIndex],idx=s.vrioTest,id=roundId(),labels=['V — Valuable?','R — Rare?','I — Costly to imitate?','O — Organized?'],opts=['Yes','No','Partly'],saved=s.vrioJudgments[id]||null;const stop=saved==='No',last=idx===3;const implication=stop?(['Competitive disadvantage: not valuable.','Competitive parity: valuable but not rare.','Temporary advantage at best: competitors can imitate.','Potential value is not fully captured: organization is lacking.'][idx]):last?'All four VRIO tests recorded.':'Continue to the next VRIO test.';return html+panel(`<div class="between">${tag('VRIO EXAMPLE '+(s.vrioIndex+1)+' / '+bank.length)}${tag('CRITERION '+(idx+1)+' / 4 · '+(q.student?'GROUP '+q.group:'PREPARED'))}</div><div class="hero-card">${H(q.text)}</div><div class="vrio-sequence">${labels.map((l,i)=>`<div class="${i===idx?'active':''}">${H(l)}</div>`).join('')}</div><h3>${H(labels[idx])}</h3><p>Discuss the evidence. You may choose Yes, No or Partly. There is no automatic right/wrong judgment.</p><div class="chips">${opts.map(x=>btn(x,'vrio-judgment',saved===x?'active':'secondary',`data-value="${x}"`)).join('')}</div>${saved?`<div class="answer-status neutral-status"><b>Class decision: ${H(saved)}</b><p>${H(implication)} ${saved==='Partly'?'Partly is treated as provisional; continue and discuss what evidence is missing.':''}</p></div>`:''}<div class="buttons">${btn('Clear choice','vrio-clear','outline')}${btn(stop||last?'Finish this resource →':'Next criterion →','next-tile','primary',saved?'':'disabled')}</div>`) }
function swotAnswer(q,cat){if(s.swot[q.id])return;const tried=s.swotWrongAttempts[q.id]||[];if(tried.includes(s.currentTeam))return message('This group has already tried this card.');const group=s.currentTeam;if(cat===q.answer){s.swot[q.id]=cat;s.swotFeedback[q.id]={good:true,group};s.teams[group].score+=1;s.currentTeam=(group+1)%3;render();const at=s.swotIndex;setTimeout(()=>{if(s.step===3&&s.swotIndex===at&&s.swotFeedback[q.id]?.good){s.swotIndex++;render()}},950);return;}soundWrong();tried.push(group);s.swotWrongAttempts[q.id]=tried;s.swotFeedback[q.id]={good:false,group,allTried:tried.length===3};if(tried.length<3){let next=(group+1)%3;while(tried.includes(next))next=(next+1)%3;s.currentTeam=next;}message('Incorrect — group '+s.teams[s.currentTeam].name+' has the next chance.');}
function swot(){const cats=[['S','Strengths'],['W','Weaknesses'],['O','Opportunities'],['T','Threats']],bank=swotBank(),idx=Math.min(s.swotIndex,bank.length),q=bank[idx],f=q?s.swotFeedback[q.id]:null;return header('Build the SWOT','Chapter 6 · One randomly shuffled statement per turn. Correct +1, then next group. Afterwards add any missing findings.')+panel(`<div class="between">${tag(q?'CARD '+(idx+1)+' / '+bank.length:'CLASS IDEAS & PHOTO SUMMARY')}${tag('Group '+s.teams[s.currentTeam].name+' · current turn')}</div>${q?`<div class="swot-focus ${f?(f.good?'answered-good':'answered-bad'):''}" draggable="true" data-swot-drag="${q.id}"><p>Drag the statement into the relevant category, or tap a quadrant.</p><h2>${H(q.text)}</h2></div>${f?`<div class="answer-status ${f.good?'answered-good':'answered-bad'}">${f.good?'✓ Correct! +1 to Group '+s.teams[f.group].name+' · next group is up.':f.allTried?'All groups have tried. Reveal or skip.':'✕ Not this category. Chance passes to Group '+s.teams[s.currentTeam].name+'.'}</div>`:''}`:`<div class="result"><strong>Prepared SWOT tiles finished.</strong><p>Now invite extra strengths, weaknesses, opportunities, and threats from the class. Award +1 to the group that contributed each new point.</p></div>`}<div class="swot-zones swot-four">${cats.map(([id,name])=>`<div class="swot-zone" data-category="${id}" ${q?'data-act="swot-drop-focus" data-value="'+id+'"':''}><h3>${H(name)}</h3>${bank.filter(x=>s.swot[x.id]===id).map(x=>`<div class="swot-card placed ${s.swot[x.id]===x.answer?'correct':'incorrect'}">${H(x.text)}</div>`).join('')}${(s.swotExtras[id]||[]).map((text,i)=>{const awarded=s.swotExtraAwards[id+':'+i];return `<div class="swot-card placed"><small>Class idea:</small> ${H(text)}<div class="extra-points"><small>${awarded?'Point to Group '+s.teams[awarded.group].name:'Award +1 to contributor:'}</small>${['A','B','C'].map((g,n)=>btn(g,'swot-extra-award',awarded?.group===n?'active':'outline',`data-value="${id}:${i}:${n}"`)).join('')}${btn('×','swot-extra-delete','outline',`data-value="${id}:${i}"`)}</div></div>`}).join('')}${!q?`<div class="swot-entry"><input id="swot-extra-${id}" placeholder="Add another ${name.slice(0,-1).toLowerCase()}" spellcheck="true">${btn('+ Add','swot-extra-add','secondary',`data-value="${id}"`)}</div>`:''}</div>`).join('')}</div>${q?`<div class="buttons">${btn('Clear choice','swot-clear','outline')}${btn('Reveal suggested category','swot-show','outline')}${btn('Skip to next statement','swot-next','secondary')}${f?.good?'':' '}</div>`:`<div class="buttons">${btn('Show SWOT photo summary →','summary-open','primary',`data-value="swot"`)}</div>`}`)}
function concerns(){const ranked=s.concernRank||[],pool=s.studentConcerns,all=ranked.map(i=>pool[i]).filter(Boolean);return header('Strategic Concerns','Chapter 6 · Record group concerns, add any missing facilitator concerns, then rank them. No correct/wrong answers or points.')+panel(`<h2>Stage 1 — Build a shared concern list</h2><p>Students identify their top concerns on handouts. Enter the groups’ suggestions first; then add any important concern from your facilitator sheet that the class missed.</p><div class="entry-row"><input id="concern-input" spellcheck="true" placeholder="A concern from the students or facilitators">${btn('Add concern','add-concern','primary')}</div><div class="pool">${pool.map((q,i)=>`<div><strong>${H(q.text)}</strong>${btn('×','remove-concern','outline',`data-value="${i}"`)}</div>`).join('')||'<p>Concerns will appear here.</p>'}</div><div class="buttons">${btn('Continue to priority ranking →','concern-rank-start','primary')}${btn('Clear list','clear-concerns','outline')}</div>${s.concernsReveal?`<div class="ranking-panel"><h2>Stage 2 — Rank the concerns</h2><p>Discuss which concern is most important. Use the arrows to reorder; the ranking is your class’s judgment, not a graded answer.</p>${all.map((q,i)=>`<div class="ranking-item"><b>${i+1}</b><span>${H(q.text)}</span><div class="buttons">${btn('↑','concern-up','outline',`data-value="${i}" ${i===0?'disabled':''}`)}${btn('↓','concern-down','outline',`data-value="${i}" ${i===all.length-1?'disabled':''}`)}</div></div>`).join('')||'<p>Add concerns to rank them.</p>'}</div>${btn('Show ranked concerns summary →','summary-open','primary',`data-value="concerns"`)}`:''}`)}
function issue(){return header('Frame the Strategic Issue','Chapter 6 · Students first write a single central challenge on their handouts. No symptom-sorting game or marked answer.')+panel(`<div class="between">${tag('ONE-SENTENCE CHALLENGE')}${tag('CLASS DISCUSSION')}</div><h2>What is the primary strategic issue facing Harbourline Creative?</h2><p>Look back at the ranked strategic concerns. Ask groups to share their sentence. Record the statement the class wants to carry forward.</p><textarea id="class-issue" rows="3" spellcheck="true" placeholder="Type the class’s one-sentence strategic issue here…">${H(s.issueStatement||'')}</textarea><div class="buttons">${btn('Save class issue','issue-save','primary')}${btn('Reveal our example issue','issue-reveal','outline')}</div>${s.issueStatement?`<div class="result"><strong>Class statement</strong><p>${H(s.issueStatement)}</p></div>`:''}${s.issueReveal?result('Our suggested issue (one possible answer)','How can Harbourline show clients the value of its marketing expertise and choose a sustainable service model as AI makes routine content easier to replace, given its limited and uneven capabilities?','Case pp. 1–7'):''}<p class="small">A useful issue is focused, evidence-based and leaves room for multiple strategic alternatives.</p>${btn('Show issue summary for photo →','summary-open','outline',`data-value="issue"`)}`)}

function allAlternatives(){return s.studentAlternative?.title?.trim()?[...D.alternatives,{id:'D',title:s.studentAlternative.title,description:s.studentAlternative.description||'Class-proposed strategic direction',benefit:s.studentAlternative.benefit||'To be evaluated by students',risk:s.studentAlternative.risk||'To be evaluated by students',capability:'Discuss required capabilities.',assumption:'Identify evidence needed to validate the choice.'}]:D.alternatives}
function alternatives(){const opts=allAlternatives();return header('Strategic Alternatives','Chapters 6–7 · Compare 3 distinct directions. Add a fourth student-proposed strategy if the class identifies a better option.')+panel(`<h2>Group discussion — propose a strategic direction</h2><p>Each group first works on its handout, weighing client value, benefits, risks and missing capabilities. Your class may also propose a fourth alternative.</p><div class="assign-grid">${opts.map(q=>`<article><h3>Option ${H(q.id)}</h3><h2>${H(q.title)}</h2><p>${H(q.description)}</p><p class="small">What benefits, risks and assumptions does it create?</p></article>`).join('')}</div><div class="student-alt-form"><h3>Optional fourth alternative — from the class</h3><p>No new alternative? Leave this blank and continue with A, B and C.</p><label>Short title<input id="alt-title" spellcheck="true" value="${H(s.studentAlternative?.title||'')}" placeholder="e.g. A focused niche strategy"></label><label>Description<textarea id="alt-description" rows="2" spellcheck="true" placeholder="What would Harbourline do differently?">${H(s.studentAlternative?.description||'')}</textarea></label><div class="entry-two"><label>Potential benefits<textarea id="alt-benefit" rows="2" spellcheck="true">${H(s.studentAlternative?.benefit||'')}</textarea></label><label>Risks or challenges<textarea id="alt-risk" rows="2" spellcheck="true">${H(s.studentAlternative?.risk||'')}</textarea></label></div><div class="buttons">${btn('Add / update Option D','alt-save','primary')}${s.studentAlternative?btn('Remove Option D','alt-remove','outline'):''}</div></div><div class="buttons">${btn('Reveal discussion comparison','alternatives-reveal','primary')}</div>${s.alternativesReveal?`<div class="alternatives">${opts.map(q=>`<article><h3>${H(q.id)}. ${H(q.title)}</h3><dl><dt>Benefits</dt><dd>${H(q.benefit)}</dd><dt>Risks / challenges</dt><dd>${H(q.risk)}</dd><dt>Capabilities</dt><dd>${H(q.capability)}</dd><dt>Assumption</dt><dd>${H(q.assumption)}</dd></dl></article>`).join('')}</div>${result('Compare alternatives rather than preferences','Strategic fit, feasibility, resources, stakeholders and uncertainty are important. Harbourline has no reliable figures for calculating projected returns.','Chapter 6')}`:''}`)}

function recommendation(){let tot=s.votes.reduce((a,b)=>a+b,0);return header('The Class Decides','Every group gives a recommendation with its evidence, benefits and risks. Then hold the class vote.')+panel(`<h2>Which strategic alternative should Harbourline pursue?</h2>${allAlternatives().map((q,i)=>`<div class="vote"><div class="between"><b>${q.id}. ${H(q.title)}</b><b>${s.votes[i]} votes</b></div><div class="vote-track"><span style="width:${tot?s.votes[i]/tot*100:0}%"></span></div>${btn('+1 vote','vote','outline',`data-value="${i}"`)}</div>`).join('')}<div class="buttons">${btn('Reveal team comparison','recommendation-reveal','primary')}${btn('Reset votes','vote-reset','outline')}</div>${s.recommendationReveal?`${result('Our team’s proposed path: C — Hybrid','Test a transparent two-part model: AI-assisted production where useful, with scoped and separately valued strategic diagnostics and advisory services. This is one defensible recommendation, not the only correct answer.','Case pp. 1–7','Which evidence might instead justify A or B?')}<div class="timeline"><h3>90-day bounded pilot</h3><p><b>Days 1–30:</b> Assign ownership, define offerings, consent and review standards.</p><p><b>Days 31–60:</b> Trial options with 5 paid clients; develop skills and approved measurement.</p><p><b>Days 61–90:</b> Review buyer willingness to pay, quality and real value; continue, change or stop.</p><small>No large technology build, immediate hiring or involuntary layoffs in the first year. Do not guarantee client sales.</small></div>`:''}`)}

function congruence(){const winnerIndex=s.votes.indexOf(Math.max(...s.votes)),best=allAlternatives()[winnerIndex]||D.alternatives[2],priorities=s.concernRank.map(i=>s.studentConcerns[i]?.text).filter(Boolean);return header('Line of Sight — 2-Minute Check','Chapter 6 · A quick consistency check, not an extra quiz. Connect the class’s choice to the evidence and strategic issue.')+panel(`<h2>Does our strategy follow from our analysis?</h2><div class="logic"><div><small>1</small><b>Evidence</b><p>AI is replacing some routine work; clients want marketing outcomes, but evidence of advisory demand remains limited.</p></div><div><small>2</small><b>Top concern</b><p>${H(priorities[0]||'Refer to the priorities ranked earlier by the class.')}</p></div><div><small>3</small><b>Strategic issue</b><p>${H(s.issueStatement||'Use the one-sentence issue from the handout.')}</p></div><div><small>4</small><b>Class’s leading alternative</b><p>${H(best.title)}${s.votes.every(v=>v===0)?' (no votes recorded yet)':''}</p></div><div><small>5</small><b>Implementation</b><p>Assign ownership; test on a 90-day pilot; measure relevant client outcomes and revisit assumptions.</p></div></div><div class="summary-insight"><b>Ask one question only:</b><p>Which link needs more evidence before Harbourline commits to this strategy?</p><small>For example, the five paid trials do not prove clients will renew annually. A different supported recommendation is still valid.</small></div>`)}

function debrief(){const top=Math.max(...s.teams.slice(0,s.teamCount).map(q=>q.score));const winners=s.teams.slice(0,s.teamCount).filter(q=>q.score===top);return header('Closing Debrief & Final Results','Recognize the top group and leave the class with one case lesson. Ask one student what evidence could change the class recommendation.')+panel(`<div class="winner">🏆 ${winners.length===1?H(winners[0].name)+' wins!':winners.map(q=>H(q.name)).join(' & ')+' tie!'}</div><div class="scoreboard-final">${s.teams.slice(0,s.teamCount).slice().sort((a,b)=>b.score-a.score).map(q=>`<div><b>${H(q.name)}</b><strong>${q.score} point${q.score===1?'':'s'}</strong></div>`).join('')}</div>${winners.length>1?'<p>For a single prize winner, ask a final evidence-based tie-breaker and award +1 to the group that answers correctly.</p>':''}<h2>Closing question: What is Harbourline’s value when AI makes content faster?</h2><p>Ask 1–2 students to share a short takeaway. AI can help make content faster, but that alone does not show a client’s marketing problem has been solved. Harbourline must make its judgment useful, repeatable and visible—and test whether clients will pay for that value.</p><p class="small">Fictional educational case · BADM 470 · Prepared for classroom discussion.</p>`)}

const stages=[quiz,external,internal,swot,concerns,issue,alternatives,recommendation,congruence,debrief];
function stage(){const cur=D.steps[s.step];const active=[0,1,2].includes(s.step),noScore=[4,5,6,7,8].includes(s.step);
 const banner=noScore?'':`<div class="turn-banner"><div><small>CURRENT TURN · EVERY CORRECT ANSWER = +1 POINT</small><strong>GROUP ${H(s.teams[s.currentTeam].name)}</strong><span>${active?'Prepared classifications are scored; class judgments are discussed.':'For open-ended analysis, facilitators award points for supported reasoning.'}</span></div>${active?'':`<div class="buttons">${btn('✓ Correct +1','mark-correct','primary')}${btn('✕ Wrong → Pass','mark-wrong','outline')}${btn('Skip group','pass-group','secondary')}</div>`}</div>`;
 return `<div class="stage"><div class="stage-top"><span class="eyebrow">STEP ${cur.num} / 10 · ${H(cur.name)}</span><div class="buttons">${btn('← Previous','prev','secondary',s.step===0?'disabled':'')}${btn('Home','home','outline')}${btn('Next step →','next','primary',s.step===9?'disabled':'')}</div></div>${banner}${stages[s.step]()}<div class="summary-shortcut">${btn('📸 Show this activity’s class summary','summary-open','outline',`data-value="${['quiz',s.tab||'pestel',s.tab||'cards','swot','concerns','issue','alternatives','recommendation','congruence','debrief'][s.step]}"`)}</div></div>`}

function landing(){return `<div class="hero"><span class="eyebrow">CAPILANO UNIVERSITY · BADM 470 · CASE FACILITATION #5</span><h1>HARBOURLINE<br><em>CREATIVE.</em></h1><h2>The Strategy Challenge</h2><p>Students analyze first. Groups defend their answers. Each correct answer earns 1 point; a wrong answer passes the chance to the next group.</p><div class="buttons">${btn('Start facilitation →','start','primary large')}${btn('See all activities ↓','scroll','outline large')}</div><div class="stats"><span><strong>10</strong>Activities</span><span><strong>+1</strong>Correct answer</span><span><strong>🏆</strong>Winning group prize</span></div></div><section id="stage-list"><span class="eyebrow">FACILITATOR-LED JOURNEY</span><h2>10 case-analysis stages.</h2><div class="stage-grid">${D.steps.map((q,i)=>`<button class="stage-card" data-act="stage" data-value="${i}"><b>${q.num}</b><strong>${H(q.title)}</strong><small>${H(q.subtitle)}</small></button>`).join('')}</div></section>`}

function mins(n){return `${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.max(0,n)%60).padStart(2,'0')}`}
const ACTIVITY_SECONDS={0:11*60,1:8*60,2:7*60,3:9*60,4:5*60,5:3*60,6:5*60,7:2*60,8:60,9:2*60};
function activitySeconds(){if(s.step===1&&s.tab==='forces')return 7*60;if(s.step===2&&s.tab==='vrio')return 7*60;return ACTIVITY_SECONDS[s.step]||5*60}
function startBigTimer(seconds){s.timer.seconds=seconds;s.timer.left=seconds;s.timer.running=true;s.timer.open=true;s.timer.endAt=Date.now()+seconds*1000;render()}
function bigTimer(){if(!s.timer.open)return '';const expired=s.timer.left<=0;const subtitle=s.screen==='stage'?D.steps[s.step].name:'Handout work';return `<div class="countdown-overlay" role="dialog" aria-modal="true" aria-label="Classroom countdown"><div class="countdown-panel"><div class="countdown-eyebrow">HARBOURLINE CREATIVE · CLASSROOM TIMER</div><h2>${expired?'Time’s up!':'Time to work on your handout'}</h2><p>${H(subtitle)} · Keep your case evidence and answers ready.</p><div class="countdown-clock ${expired?'time-expired':''}" id="big-timer-clock" aria-live="off">${mins(s.timer.left)}</div><div class="countdown-controls"><button class="btn ${s.timer.running?'outline':'primary'}" data-act="timer-pause">${s.timer.running?'Pause timer':'Resume timer'}</button><button class="btn outline" data-act="timer-restart">Restart</button></div><label class="countdown-label" for="big-duration">Set countdown time</label><select id="big-duration" aria-label="Countdown duration">${[60,120,180,240,300,420,480,540,600,660,720,840,900].map(n=>`<option value="${n}" ${n===s.timer.seconds?'selected':''}>${n/60} minute${n===60?'':'s'}</option>`).join('')}</select><div class="countdown-presets"><button class="btn outline" data-act="timer-five">5 min · handout</button><button class="btn outline" data-act="timer-activity">${Math.round(activitySeconds()/60)} min · activity</button></div><button class="btn primary countdown-end" data-act="timer-end">${expired?'Time’s up — continue':'Time’s up / End Early'}</button><small>Ending the timer returns you to exactly where you were in the activity.</small></div></div>`}
function controls(){return `<div class="shade ${s.facilitator?'visible':''}" data-act="close"></div><aside class="drawer ${s.facilitator?'visible':''}"><div class="drawer-head"><h2>Facilitator Controls</h2>${btn('✕','close','secondary')}</div><div class="drawer-body"><h3>Jump to stage</h3><div class="drawer-steps">${D.steps.map((q,i)=>btn(`${q.num} ${H(q.name)}`,'stage',s.step===i&&s.screen==='stage'?'active':'outline',`data-value="${i}"`)).join('')}</div><h3>Presentation</h3>${btn('Fullscreen','fullscreen','outline full')}${btn(s.projector?'Disable projector mode':'Enable projector mode','projector','outline full')}<h3>Discussion timer</h3><select id="duration">${[0,60,120,180,300,420,600].map(n=>`<option value="${n}" ${n===s.timer.seconds?'selected':''}>${n===0?'Off':n/60+' minutes'}</option>`).join('')}</select><div class="timer">${mins(s.timer.left)}</div><div class="buttons">${btn(s.timer.running?'Pause':'Start','timer-toggle','primary')}${btn('Reset','timer-reset','outline')}</div><h3>Teams and scoring</h3><select id="team-count"><option value="3">3 groups</option></select>${s.teams.slice(0,s.teamCount).map((q,i)=>`<div class="team"><input data-team="${i}" value="${H(q.name)}" aria-label="Group ${i+1} name"><b>${q.score}</b>${btn('+1','team-add','secondary',`data-value="${i}"`)}${btn('−1','team-sub','secondary',`data-value="${i}"`)}${btn('Turn','team-turn','outline',`data-value="${i}"`)}</div>`).join('')}<p class="small">Correct +1 records a point once per round. Wrong passes to a new group. Facilitators decide open-ended answers; manual score adjustment is available here.</p><h3>Round controls</h3>${btn('Reveal current answer','reveal','outline full')}${btn('Reset current answer','reset','outline full')}${btn('Reset entire class session','reset-all','danger full')}</div></aside>`}

function render(){const teams=s.teams.slice(0,s.teamCount);root.innerHTML=`<div class="shell ${s.projector?'projector':''}"><header class="topbar"><button class="brand" data-act="home"><span class="logo">H✦</span><span>HARBOURLINE <small>THE STRATEGY CHALLENGE</small></span></button><span class="progress">${s.screen==='stage'?`STEP ${D.steps[s.step].num} / 10`:'CASE FACILITATION'}<i style="width:${s.screen==='stage'?(s.step+1)*10:0}%"></i></span><div class="buttons">${btn('⏱ Timer · 05:00','timer-open','primary timer-top')}${btn('⛶','fullscreen','outline')}${btn('⚙ Facilitator','facilitator','outline')}</div></header><div class="scoreline">${teams.map((q,i)=>`<span class="${s.currentTeam===i?'active':''}">${H(q.name)} <b>${q.score} pt</b></span>`).join('')}</div><main>${s.screen==='home'?landing():s.summaryView?summaryScreen(s.summaryView):stage()}</main><footer>BADM 470 · Fictional teaching case · Students first, then facilitator reveal · Anderson, Buengel & Simpson (2025)</footer>${controls()}${bigTimer()}</div>`;try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}}

function message(t){toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2500)}
function nav(i){s.summaryView=null;s.step=Math.max(0,Math.min(9,i));s.index=0;s.tab='';s.facilitator=false;s.screen='stage';s.timer.running=false;s.timer.open=false;s.timer.endAt=null;s.timer.left=s.timer.seconds;s.attempted=[];s.scoreTile=null;render();scrollTo(0,0)}
function advance(){if(s.step===0){if(s.index<D.quiz.length-1)s.index++;else return nav(1)}else if(s.step===1){if((s.tab||'pestel')==='pestel'){if(s.index<D.pestel.length-1)s.index++;else{s.pestelSummary=true}}else if(s.tab==='forces'){if(s.index<D.forces.length-1)s.index++;else return nav(2)}}s.attempted=[];render()}

function reveal(){const key=qkey();if(s.step===0||s.step===1){dispatch(s.step===0?'show-quiz':'reveal-tile');return}if(s.step===2){dispatch('reveal-tile');return}if(s.step===3){s.swotReveal=true}if(s.step===4)s.concernsReveal=true;if(s.step===5){s.sortReveal=true;s.issueReveal=true}if(s.step===6)s.alternativesReveal=true;if(s.step===7)s.recommendationReveal=true;if(s.step===8)s.chainReveal=true;render()}

function reset(){const key=qkey();delete s.checked[key];delete s.selected[key];s.resolved[`${s.step}:${s.tab||'main'}:${s.step===2&&s.tab==='vrio'?s.vrioIndex+'-'+s.vrioTest:s.index}:${[2,3,4,5,6,7,9].includes(s.step)?s.scoreTile||'open':''}`]=false;s.attempted=[];if(s.step===2)s.vrioReveal=false;if(s.step===3)s.swotReveal=false;if(s.step===4)s.concernsReveal=false;if(s.step===5)s.sortReveal=false;if(s.step===6)s.alternativesReveal=false;if(s.step===7)s.recommendationReveal=false;if(s.step===8)s.chainReveal=false;render()}

function printHandout(type){const w=window.open('','_blank');if(!w)return message('Allow popups to print handouts.');const issue=type==='issue';let html=issue?`<h2>Write your central strategic issue in one sentence</h2><p>Use the case evidence and the 5 major concerns. Do not jump to a solution.</p><h3>Issue statement</h3>${'<div class="line"></div>'.repeat(4)}<h3>Supporting case evidence</h3>${'<div class="line"></div>'.repeat(3)}`:`<h2>Develop three realistic strategic alternatives</h2><p>Each alternative should address the same issue while making meaningfully different trade-offs.</p>${['Strategic direction','Client value','Benefits','Risks','Capabilities','Key assumption'].map(label=>`<table><tr><th>${label}</th><th>Alternative 1</th><th>Alternative 2</th><th>Alternative 3</th></tr><tr><td></td><td></td><td></td><td></td></tr></table>`).join('')}`;w.document.write(`<html><head><title>Harbourline student handout</title><style>body{font:14px Arial;padding:26px;color:#182635}.line{height:28px;border-bottom:1px solid #aaa}table{width:100%;border-collapse:collapse;margin:9px 0}td,th{height:42px;border:1px solid #aaa;padding:6px}th{background:#eaf0f4}</style></head><body><h1>BADM 470 · Harbourline Creative</h1><p>Group: ____________ Names: ______________________________</p>${html}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function dispatch(act,v){const key=qkey(),entry=s.selected[key],round=`${s.step}:${s.tab||'main'}:${s.index}:${s.scoreTile||'open'}`;const nextGroup=()=>{s.currentTeam=(s.currentTeam+1)%3};switch(act){
case 'summary-open':return openSummary(v);case 'summary-back':s.summaryView=null;break;case 'summary-next':return summaryNext();
case 'home':s.summaryView=null;s.screen='home';s.facilitator=false;s.timer.running=false;break;
case 'start':return nav(0);case 'stage':return nav(+v);case 'prev':return nav(s.step-1);case 'next':return nav(s.step+1);
case 'scroll':$('#stage-list')?.scrollIntoView({behavior:'smooth'});return;
case 'facilitator':s.facilitator=true;break;case 'close':s.facilitator=false;break;
case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>message('Fullscreen unavailable'));return;
case 'projector':s.projector=!s.projector;break;
case 'tab':s.tab=v;s.index=0;s.attempted=[];break;
case 'save-collection':{const groupNames=['A','B','C'];const prev=(s.studentAnswers[v]||[]).filter(q=>q.text),skips=s.skippedEvidence?.[v]||{};const next=groupNames.map(g=>({text:skips[g]?'':($('#collect-'+g)?.value||'').trim().replace(/\s+/g,' '),group:g})).filter(q=>q.text);for(const q of next){if(!prev.some(p=>p.group===q.group)){s.teams[groupNames.indexOf(q.group)].score+=1}}s.studentAnswers[v]=next;s.collection[v]=true;const count=bankOf(v).length;const order=Array.from({length:count},(_,i)=>i);for(let i=count-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}s.tileOrder[v]=order;s.index=0;s.vrioIndex=0;s.vrioTest=0;message(next.length+' class tile(s) added; contributors earned +1 each.');break;}
case 'skip-evidence':{s.skippedEvidence=s.skippedEvidence||{};s.skippedEvidence[v]=s.skippedEvidence[v]||{};const box=$('#collect-'+v);const checked=!s.skippedEvidence[s.tab||'pestel']?.[v];s.skippedEvidence[s.tab||'pestel'][v]=checked;if(box){box.disabled=checked;if(checked)box.value='';}break;}

case 'quiz-answer':{if(s.roundResults[roundId()])return;const q=D.quiz[s.index];grade(+v===q.answer,'Option '+ 'ABCD'[q.answer]+' — '+q.options[q.answer],q.explanation,q.source,+v);break;}
case 'pestel-answer':{if(s.roundResults[roundId()])return;const q=bankOf('pestel')[s.index];if(q.student){neutralChoice(v);break;}grade(v===q.answer,q.answer,q.explanation,q.source,v,false);if(s.roundFeedback[roundId()]?.good&&s.roundFeedback[roundId()]?.submitted===v)s.checked['category:'+q.id]=v;break;}
case 'force-answer':{if(s.roundResults[roundId()])return;const q=bankOf('forces')[s.index];if(q.student){neutralChoice(v);break;}grade(v===q.force,q.force,q.explanation,q.source,v,false);break;}
case 'rc-answer':{if(s.roundResults[roundId()])return;const q=bankOf('cards')[s.index];if(q.student){neutralChoice(v);break;}grade(v===q.answer,q.answer,q.explanation,q.source,v,false);break;}
case 'vrio-judgment':s.vrioJudgments[roundId()]=v;break;case 'vrio-clear':delete s.vrioJudgments[roundId()];break;
case 'force-finish':{s.forceRatings[roundId()]=s.forceRatings[roundId()]||'Moderate';const bank=bankOf('forces');s.index++;s.currentTeam=(s.currentTeam+1)%3;if(s.index>=bank.length)return openSummary('forces');break;}case 'clear-choice':clearChoice();break;case 'next-tile':{const t=s.step===1?s.tab||'pestel':s.step===2?s.tab||'cards':'';if(s.step===2&&t==='vrio'){const judgment=s.vrioJudgments[roundId()];if(!judgment)return message('Choose Yes, No or Partly first.');const finish=judgment==='No'||s.vrioTest===3;if(!finish)s.vrioTest++;else{s.vrioTest=0;s.vrioIndex++;s.currentTeam=(s.currentTeam+1)%3;if(s.vrioIndex>=bankOf('vrio').length)return openSummary('vrio')}render();return}if(s.step===2&&t==='cards'){s.index++;s.currentTeam=(s.currentTeam+1)%3;if(s.index>=bankOf('cards').length)return openSummary('cards');break;}if(s.step===1){s.index++;s.currentTeam=(s.currentTeam+1)%3;if(s.index>=bankOf(t).length){if(t==='pestel'){s.pestelSummary=true;return openSummary('pestel')}else return openSummary('forces')}break;}if(s.step===0){s.index++;s.currentTeam=(s.currentTeam+1)%3;if(s.index>=D.quiz.length)return openSummary('quiz')}break;}
case 'to-forces':s.tab='forces';s.index=0;s.pestelSummary=false;break;
case 'show-quiz':{const q=D.quiz[s.index],id=roundId();s.roundResults[id]=true;s.roundFeedback[id]={good:true,unscored:true,group:s.currentTeam,expected:'Option '+'ABCD'[q.answer]+' — '+q.options[q.answer],explanation:q.explanation,source:q.source,submitted:null};break;}
case 'reveal-tile':{const id=roundId(),t=s.step===1?(s.tab||'pestel'):(s.tab||'cards');const q=s.step===1?bankOf(t)[s.index]:t==='vrio'?bankOf(t)[s.vrioIndex]:bankOf(t)[s.index];const expected=q.student?'Class-generated example (no fixed answer)':t==='pestel'?q.answer:t==='forces'?q.force:t==='vrio'?q.answers[s.vrioTest]:q.answer;s.roundResults[id]=true;s.roundFeedback[id]={good:true,unscored:true,group:s.currentTeam,expected,explanation:q.explanation||'Facilitator to confirm the interpretation.',source:q.source,submitted:null};if(s.step===1&&t==='pestel'&&!q.student)s.checked['category:'+q.id]=expected;break;}
case 'mark-correct':if(s.resolved[round])return message('Already awarded for this round');s.teams[s.currentTeam].score+=1;s.resolved[round]=true;message('+1 Group '+s.teams[s.currentTeam].name);nextGroup();break;
case 'mark-wrong':soundWrong();message('Incorrect — chance passes to Group '+s.teams[(s.currentTeam+1)%3].name);nextGroup();break;
case 'pass-group':nextGroup();break;case 'team-turn':s.currentTeam=+v;break;
case 'pick':s.selected[key]=+v;break;case 'select-chip':s.selected[key]=v;break;
case 'force':s.selected[key]={...(entry||{}),force:v};break;case 'force-drop':if(s.forceSelected)s.selected[key]={...(entry||{}),force:s.forceSelected};break;case 'level':s.selected[key]={...(entry||{}),level:v};break;
case 'check':s.checked[key]=true;break;case 'next-round':advance();return;
case 'pestel-restart':s.pestelSummary=false;s.index=0;break;
case 'reveal':reveal();return;case 'reset':reset();return;
case 'add-resource':{const x=$('#student-resource');if(!x||!x.value.trim())return message('Enter a student answer');s.studentResources.push({text:x.value.trim().replace(/\s+/g,' '),answer:null,group:s.teams[s.currentTeam].name});break;}
case 'resource-select':s.resourceSelected=s.resourceSelected===v?null:v;s.scoreTile=v;break;
case 'resource-place':if(s.resourceSelected){s.scoreTile=s.resourceSelected;s.resourcePlaced[s.resourceSelected]=v;s.resourceSelected=null;s.resourceReveal=false}break;
case 'resource-remove':delete s.resourcePlaced[v];s.resourceReveal=false;break;case 'resource-reveal':s.resourceReveal=true;break;case 'resource-reset':s.resourcePlaced={};s.resourceSelected=null;s.resourceReveal=false;break;
case 'vrio-pick':s.selected[`vrio-${s.vrioIndex}-${s.vrioTest}`]=v;break;case 'vrio-check':case 'vrio-reveal':s.vrioReveal=true;break;case 'vrio-reset':s.vrioReveal=false;break;case 'vrio-next':s.vrioTest=(s.vrioTest+1)%4;break;
case 'swot-drop-focus':{const q=swotBank()[s.swotIndex];if(q)swotAnswer(q,v);break;}
case 'swot-show':{const q=swotBank()[s.swotIndex];if(q){s.swot[q.id]=q.answer;s.swotFeedback[q.id]={good:true,unscored:true,group:s.currentTeam};s.swotIndex++;s.currentTeam=(s.currentTeam+1)%3;}break;}
case 'swot-clear':{const q=swotBank()[s.swotIndex];if(q){delete s.swot[q.id];delete s.swotFeedback[q.id];delete s.swotWrongAttempts[q.id];}break;}
case 'swot-next':{const q=swotBank()[s.swotIndex];if(q){delete s.swotFeedback[q.id];s.swotIndex++;s.currentTeam=(s.currentTeam+1)%3;}break;}
case 'swot-extra-add':{const x=$('#swot-extra-'+v);if(x?.value.trim())s.swotExtras[v].push(x.value.trim());break;}
case 'swot-extra-award':{const [cat,num,g]=v.split(':'),k=cat+':'+num,previous=s.swotExtraAwards[k],n=+g;if(previous?.group===n)break;if(previous)s.teams[previous.group].score=Math.max(0,s.teams[previous.group].score-1);s.teams[n].score+=1;s.swotExtraAwards[k]={group:n};message('+1 for Group '+s.teams[n].name);break;}
case 'swot-extra-delete':{const [cat,num]=v.split(':'),i=+num,prior=s.swotExtraAwards[cat+':'+i];if(prior)s.teams[prior.group].score=Math.max(0,s.teams[prior.group].score-1);s.swotExtras[cat].splice(i,1);const all={};for(const [key,item] of Object.entries(s.swotExtraAwards)){const [c,n]=key.split(':');if(c===cat){if(+n===i)continue;all[c+':'+(+n>i?+n-1:+n)]=item}else all[key]=item} s.swotExtraAwards=all;break;}
case 'concern-rank-start':s.concernsReveal=true;s.concernRank=s.studentConcerns.map((_,i)=>i);break;
case 'concern-up':{const i=+v;if(i>0)[s.concernRank[i-1],s.concernRank[i]]=[s.concernRank[i],s.concernRank[i-1]];break;}
case 'concern-down':{const i=+v;if(i<s.concernRank.length-1)[s.concernRank[i+1],s.concernRank[i]]=[s.concernRank[i],s.concernRank[i+1]];break;}
case 'swot-select':s.swotSelected=s.swotSelected===v?null:v;s.scoreTile=v;break;
case 'swot-place':if(s.swotSelected){s.scoreTile=s.swotSelected;s.swot[s.swotSelected]=v;s.swotSelected=null;s.swotReveal=false}break;
case 'swot-remove':delete s.swot[v];s.swotReveal=false;break;case 'swot-check':s.swotReveal=true;break;case 'swot-reveal':D.swot.forEach(q=>s.swot[q.id]=q.answer);s.swotReveal=true;break;case 'swot-reset':s.swot={};s.swotSelected=null;s.swotReveal=false;break;
case 'add-concern':{const x=$('#concern-input');if(!x||!x.value.trim())return message('Enter a student concern');s.studentConcerns.push({text:x.value.trim().replace(/\s+/g,' '),team:'Class'});s.concernRank=s.studentConcerns.map((_,i)=>i);break;}
case 'remove-concern':s.studentConcerns.splice(+v,1);s.concernRank=s.studentConcerns.map((_,i)=>i);break;case 'clear-concerns':if(confirm('Clear student concerns?'))s.studentConcerns=[];s.concernRank=[];break;case 'concern-reveal':s.concernsReveal=true;break;
case 'sort-select':s.sortSelected=s.sortSelected===v?null:v;s.scoreTile=v;break;
case 'sort-place':if(s.sortSelected){s.scoreTile=s.sortSelected;s.sortPlaced[s.sortSelected]=v;s.sortSelected=null;s.sortReveal=false}break;
case 'sort-remove':delete s.sortPlaced[v];s.sortReveal=false;break;case 'sort-reveal':s.sortReveal=true;break;case 'sort-reset':s.sortPlaced={};s.sortSelected=null;s.sortReveal=false;break;
case 'issue-save':s.issueStatement=($('#class-issue')?.value||'').trim();message('Class issue saved');break;case 'alt-save':{const title=($('#alt-title')?.value||'').trim();if(!title)return message('Enter a title for the proposed alternative.');s.studentAlternative={title,description:($('#alt-description')?.value||'').trim(),benefit:($('#alt-benefit')?.value||'').trim(),risk:($('#alt-risk')?.value||'').trim()};while(s.votes.length<4)s.votes.push(0);message('Option D added to the class vote.');break;}case 'alt-remove':s.studentAlternative=null;s.votes=s.votes.slice(0,3);break;case 'issue-reveal':s.issueReveal=true;break;case 'alternatives-reveal':s.alternativesReveal=true;break;case 'recommendation-reveal':s.recommendationReveal=true;break;
case 'vote':{const i=+v;while(s.votes.length<allAlternatives().length)s.votes.push(0);s.votes[i]++;break;}case 'vote-reset':s.votes=allAlternatives().map(()=>0);break;
case 'chain-pick':s.chainAnswer=+v;s.chainReveal=false;break;case 'chain-check':case 'chain-reveal':s.chainReveal=true;break;
case 'timer-open':return startBigTimer(300);
case 'timer-five':return startBigTimer(300);
case 'timer-activity':return startBigTimer(activitySeconds());
case 'timer-pause':if(s.timer.running){s.timer.left=Math.max(0,Math.ceil((s.timer.endAt-Date.now())/1000));s.timer.running=false;s.timer.endAt=null}else if(s.timer.left>0){s.timer.running=true;s.timer.endAt=Date.now()+s.timer.left*1000}break;
case 'timer-restart':return startBigTimer(s.timer.seconds);
case 'timer-end':s.timer.running=false;s.timer.open=false;s.timer.endAt=null;s.timer.left=s.timer.seconds;break;
case 'timer-toggle':if(s.timer.running){s.timer.left=Math.max(0,Math.ceil((s.timer.endAt-Date.now())/1000));s.timer.running=false;s.timer.endAt=null}else if(s.timer.left>0){s.timer.running=true;s.timer.endAt=Date.now()+s.timer.left*1000}break;
case 'timer-reset':s.timer.left=s.timer.seconds;s.timer.running=false;s.timer.endAt=null;break;
case 'team-add':s.teams[+v].score+=1;break;case 'team-sub':s.teams[+v].score=Math.max(0,s.teams[+v].score-1);break;
case 'reset-all':if(!confirm('Reset all browser progress and points?'))return;s=fresh();break;
}render()}

root.addEventListener('click',e=>{if(e.target.matches('input,textarea'))return;const b=e.target.closest('[data-act]');if(b){dispatch(b.dataset.act,b.dataset.value)}});
root.addEventListener('change',e=>{const t=e.target;if(t.dataset.skip){const topic=t.dataset.topic;s.skippedEvidence=s.skippedEvidence||{};s.skippedEvidence[topic]=s.skippedEvidence[topic]||{};s.skippedEvidence[topic][t.dataset.skip]=t.checked;const field=$('#collect-'+t.dataset.skip);if(field){field.disabled=t.checked;if(t.checked)field.value='';}return;}if(t.id==='pressure-meter'){s.forceRatings[roundId()]=['Low','Moderate','High'][+t.value];const label=$('#pressure-value');if(label)label.textContent=s.forceRatings[roundId()];return;}if(t.id==='big-duration'){startBigTimer(+t.value);return;}if(t.id==='duration'){s.timer.seconds=+t.value;s.timer.left=+t.value;s.timer.running=false;s.timer.endAt=null;render()}else if(t.id==='team-count'){s.teamCount=3;s.currentTeam=Math.min(s.currentTeam,2);render()}});
root.addEventListener('input',e=>{if(e.target.dataset.team!==undefined){s.teams[+e.target.dataset.team].name=e.target.value;localStorage.setItem(KEY,JSON.stringify(s))}});
let dragItem=null;
root.addEventListener('dragstart',e=>{const el=e.target.closest('[data-swot-drag],[data-resource-drag],[data-sort-drag],[data-force-drag]');if(el){dragItem={type:el.dataset.swotDrag?'swot':el.dataset.resourceDrag?'resource':el.dataset.sortDrag?'sort':'force',id:el.dataset.swotDrag||el.dataset.resourceDrag||el.dataset.sortDrag||el.dataset.forceDrag};e.dataTransfer.setData('text/plain',dragItem.id)}});
root.addEventListener('dragover',e=>{if(e.target.closest('[data-category],[data-rc-category],[data-sort-category],[data-force-drop]'))e.preventDefault()});
root.addEventListener('drop',e=>{const c=e.target.closest('[data-category],[data-rc-category],[data-sort-category],[data-force-drop]');if(!c||!dragItem)return;e.preventDefault();if(dragItem.type==='swot'&&c.dataset.category){const q=swotBank()[s.swotIndex];if(q&&q.id===dragItem.id){swotAnswer(q,c.dataset.category);s.swotReveal=false}}if(dragItem.type==='resource'&&c.dataset.rcCategory){s.scoreTile=dragItem.id;s.resourcePlaced[dragItem.id]=c.dataset.rcCategory;s.resourceReveal=false}if(dragItem.type==='sort'&&c.dataset.sortCategory){s.scoreTile=dragItem.id;s.sortPlaced[dragItem.id]=c.dataset.sortCategory;s.sortReveal=false}if(dragItem.type==='force'&&c.dataset.forceDrop){const k=qkey();s.selected[k]={...(s.selected[k]||{}),force:dragItem.id}}dragItem=null;render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&s.timer.open){s.timer.running=false;s.timer.open=false;s.timer.endAt=null;render()}});
setInterval(()=>{if(s.timer.running){s.timer.left=Math.max(0,Math.ceil((s.timer.endAt-Date.now())/1000));const t=$('.timer');if(t)t.textContent=mins(s.timer.left);const big=$('#big-timer-clock');if(big)big.textContent=mins(s.timer.left);if(s.timer.left===0){s.timer.running=false;s.timer.endAt=null;if(s.timer.open)render();message('Time’s up!')}try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}}},250);
render();
